import os, re, json
from collections import Counter

d = os.environ['RLM_SESSION_DIR']
t = open(d + '/../../sessions/' + os.path.basename(d) + '.jsonl').read().replace('\\n', '\n')

pattern = r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):'

demo_data = {}
for m in re.finditer(pattern, t):
    label = m.group(1)
    height = int(m.group(2))
    width = int(m.group(3))

    start = m.end()
    lines = []
    pos = start
    while len(lines) < height and pos < len(t):
        line = t[pos:].split('\n')[0].strip()
        if line:
            lines.append(line)
        pos += t[pos:].find('\n') + 1

    demo_data[label] = [[int(x) for x in l.split()] for l in lines]

def predict(grid):
    out_rows = []
    for r in range(len(grid)):
        row = grid[r]
        bg_val = max(Counter(row).items(), key=lambda x: x[1])[0]

        features = set()
        for c, val in enumerate(row):
            if val == bg_val or val == 0:
                continue

            if val % 2 == 1:
                if 0 <= c < 13:
                    features.add(c)
            else:
                mapped = c - 14
                if 0 <= mapped < 13:
                    features.add(mapped)

        out_row = [3] * 13
        for f in sorted(features, reverse=True):
            out_row[f] = 2
        out_rows.append(out_row)

    return out_rows

